
CREATE TABLE CORE_DIM.T_DIM_LOCAL_PRODUCT (
	PROD_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product.',
	COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country organization.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country for which this country organization is responsible. (The business country is not identical to a political country.)',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	LOCAL_PROD_NR VARCHAR(100) NOT NULL COMMENT 'The number which identifies the product within the given market / internal organization. (i.e. the local item number)  Note that the product number is unique for a certain point in time, but may be re-used later on.',
	ALT_1_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the first additional product number.',
	ALT_2_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the second additional product number.',
	ALT_3_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the third additional product number.',
	ALT_4_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the forth additional product number.',
	ALT_5_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the fifth additional product number.',
	ALT_6_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the sixth additional product number.',
	ALT_7_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the seventh additional product number.',
	ALT_8_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the eight additional product number.',
	ALT_9_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the ninth additional product number.',
	ALT_10_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the tenth additional product number.',
    ALT_11_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the eleventh additional product number.',
	ALT_12_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the twelveth additional product number.',
	ALT_13_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the thirteenth additional product number.',
	ALT_14_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the forteenth additional product number.',
	ALT_15_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the fifteenth additional product number.',
    ALT_16_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the sixteenth additional product number.',
	ALT_17_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the seventeenth additional product number.',
	ALT_18_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the eighteenth additional product number.',
	ALT_19_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the nineteenth additional product number.',
	ALT_20_LOCAL_PROD_NR VARCHAR(100) COMMENT 'A product may be identified by more than one product number within a country organization. In this case, this is the twentieth additional product number.',
    ALT_LOCAL_PROD_NR_CNT NUMBER(38,0) NOT NULL COMMENT 'A product may be identified by more than one product number within a country organization. This is the total number of additional product numbers that exist in the given country organization. (Note that only the first five product numbers are stored in the columns alt_<n>_local_prod_nr.)',
	LOCAL_PROD_NAME VARCHAR(250) NOT NULL COMMENT 'The name by which the product is marketed within the given market / internal organization. (This is the local product name.)',
	LOCAL_PROD_DESCR VARCHAR(250) COMMENT 'A more detailed (free text) description for the product - which applies to the given market / internal organization.',
	LOCAL_PROD_VERSION_NR VARCHAR(20) COMMENT 'The version number of the product in the given market / internal company.',
	LOCAL_PROD_CREATION_DT DATE COMMENT 'The date when the product was created in the operational system for the given market / internal company.',
	PLU_NR VARCHAR(20) COMMENT 'Price Lookup Code; a 4 or 5 digit code to identify items, used mostly for fruits and vegetables.',
	PROD_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the general lifecycle status for products.',
	PROD_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the general lifecycle status for products. (Description in group language, i.e. in German)',
	BRAND_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'A code that identifies the brand type. (own brand vs. private brand)',
	BRAND_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the brand type (own brand vs. private brand). (Description in group language, i.e.in German)',
	BRAND_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the brand.',
	SUP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the supplier of this product for the given country organization.',
	SUP_NAME VARCHAR(100) NOT NULL COMMENT 'The name by which the supplier is known.',
	BUYER_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee, who negotiated this product for the given country organization.',
	BUYER_NR VARCHAR(20) NOT NULL COMMENT 'The number which identifies the buyer within the organization.',
	LOCAL_LIST_DT DATE COMMENT 'The date when the product was first listed in the given market / internal company.',
	LOCAL_DELIST_DT DATE COMMENT 'The date when the product was removed from the assortment in the given market / internal company.',
	INTRASTAT_NR VARCHAR(20) NOT NULL COMMENT 'The Intrastat number which identifies a certain class of products.',
	INTRASTAT_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the Intrastat number. This is the eight-digit number. (Name in group language, i.e. in German)',
	LOCKED_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product has been locked for the given market / internal company. In that case the product cannot be sold, but may still be returned.',
	VAT_REFUND_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product is elegible for VAT refund in the given market.',
	DANGEROUS_GOODS_FG BOOLEAN NOT NULL COMMENT 'An indicator for hazardous material.',
	COUNTRY_SPECIFIC_PROD_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the underlying product has been defined by only one country organization and is therefore available only in one country. (This does not include products, which are defined globally, but which happen to be sold in only one country.) On product variant level this means, that this is the only variant of the product.',
	DISPATCH_GRP_NR VARCHAR(20) NOT NULL COMMENT 'The number which identifies the dispatch group, i.e. the group of products which are handled together in the logistics process.',
	DISPATCH_GRP_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the dispatch group. (Description in group language, i.e. in German)',
	DISPATCH_UNIT_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit of measure by which products get ordered, e.g. by pallet, by layer on a pallet, etc.',
	DISPATCH_UNIT_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the unit of measure by which products get ordered, e.g. by pallet, by layer on a pallet, etc. (Description in group language, i.e. in German)',
	LIST_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the listing type, e.g. regular assortment, seasonal products, promotional items, etc.',
	LIST_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the listing type. E.g. regular assortment, seasonal products, promotional items, etc. (Description in group language, i.e. in German)',
	ORDER_AREA_NR VARCHAR(20) NOT NULL COMMENT 'The number which identifies the order area.',
	ORDER_AREA_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the order area. (Description in group language, i.e. in German)',
	MIN_CUST_AGE_MEAS NUMBER(38,5) COMMENT 'The minimum age for a customer who wants to purchase this product.',
	SORT_SEQ NUMBER(38,0) COMMENT 'The sort order of the product on lists. The sort order is relative to the item family of the product.',
	MIN_CONSUMPTION_DAY_CNT NUMBER(38,0) COMMENT 'The minimum amount of life (in number of days) an item must have remaining when bought by a customer.',
	MIN_SHELFLIFE_TO_STORE_DAY_CNT NUMBER(38,0) COMMENT 'The minimum amount of shelf life (in number of days) an item must have remaining when delivered to a store.',
	MIN_SHELFLIFE_TO_WH_DAY_CNT NUMBER(38,0) COMMENT 'The minimum amount of life (in number of days) an item must have remaining when delivered to the warehouse.',
	DELIV_TEMP_MEAS NUMBER(38,5) COMMENT 'The (recommended) delivery temperature for the product.',
	MIN_DELIV_TEMP_MEAS NUMBER(38,5) COMMENT 'The minimum delivery temperature for the product.',
	MAX_DELIV_TEMP_MEAS NUMBER(38,5) COMMENT 'The maximum delivery temperature for the product.',
	UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit of measure.',
	SHELFLIFE_CHECK_ON_RECEIPT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the minimum shelflife for this product shall be checked upon receipt.',
	ITEM_FAM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the item family to which this product belongs.',
	ITEM_FAM_NR VARCHAR(100) COMMENT 'The number by which the related item family is known to business.',
	ITEM_FAM_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the item family. (Name in group language, i.e. in German)',
	SUB_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a sub item group to which this product belongs.',
	SUB_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related sub item group is known to business.',
	SUB_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the sub item group. (Name in group language, i.e. in German)',
	INT_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier [surrogate key] for an international item group to which this product belongs.',
	INT_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related international item group is known to business.',
	INT_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the international item group. (Name in group language, i.e. in German)',
	PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the pillar, to which this product belongs.',
	PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related pillar is known to business.',
	PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the pillar.(Name in group language, i.e. in German)',
	MAIN_PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the main pillar, to which this product belongs.',
	MAIN_PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related main pillar is known to business.',
	MAIN_PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the main pillar. (Name in group language, i.e. in German)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	CONSTRAINT PK_T_DIM_LOCAL_PRODUCT PRIMARY KEY (PROD_SID, COUNTRY_ORG_SID, DWH_VALID_FROM_TMSP)
)COMMENT='This dimension contains the properties of a product, as they are defined by a country organization.';